"""Independent analytic contraction of the frozen order-five forward jet.

This file deliberately contains no import from either depth-order-five
population compiler.  It starts from the literal frozen-line product and
chain rules and eliminates the local Gaussian coordinates by the elementary
one-coordinate Wick--Stein identity.  Its output is a seven-scalar,
unit-forward-Gram recurrence for the straight fifth directional derivative.

The recurrence is only one (important) sector of ``D^5 f``.  The companion
note ``ANALYTIC_ROUTE.md`` explains why it is not promoted to a recurrence
for the complete coefficient before the mixed Hessian sectors are closed.
"""

from __future__ import annotations

from collections import defaultdict
from dataclasses import dataclass
from fractions import Fraction
from functools import lru_cache
import hashlib
import json
from pathlib import Path
from typing import Iterable, Mapping


# ---------------------------------------------------------------------------
# Sparse deterministic commutative polynomials.
# ---------------------------------------------------------------------------

SMonomial = tuple[str, ...]
SPoly = dict[SMonomial, Fraction]


def sc(value: int | Fraction) -> SPoly:
    value = Fraction(value)
    return {} if not value else {(): value}


def sv(name: str) -> SPoly:
    return {(name,): Fraction(1)}


def sa(*values: Mapping[SMonomial, Fraction]) -> SPoly:
    out: defaultdict[SMonomial, Fraction] = defaultdict(Fraction)
    for value in values:
        for monomial, coefficient in value.items():
            out[monomial] += coefficient
    return {m: c for m, c in out.items() if c}


def ss(value: Mapping[SMonomial, Fraction], factor: int | Fraction) -> SPoly:
    factor = Fraction(factor)
    return {} if not factor else {m: factor * c for m, c in value.items() if c}


def sm(left: Mapping[SMonomial, Fraction], right: Mapping[SMonomial, Fraction]) -> SPoly:
    if not left or not right:
        return {}
    out: defaultdict[SMonomial, Fraction] = defaultdict(Fraction)
    for lm, lc in left.items():
        for rm, rc in right.items():
            out[tuple(sorted(lm + rm))] += lc * rc
    return {m: c for m, c in out.items() if c}


def sp(value: Mapping[SMonomial, Fraction], exponent: int) -> SPoly:
    if exponent < 0:
        raise ValueError("negative exponent")
    out = sc(1)
    base = dict(value)
    power = exponent
    while power:
        if power & 1:
            out = sm(out, base)
        power //= 2
        if power:
            base = sm(base, base)
    return out


def sproduct(*values: Mapping[SMonomial, Fraction]) -> SPoly:
    out = sc(1)
    for value in values:
        out = sm(out, value)
    return out


def atom_name(counts: tuple[int, ...]) -> str:
    if len(counts) != 6:
        raise ValueError(counts)
    if counts == (2, 0, 0, 0, 0, 0):
        return "1"
    return "M" + "".join(str(value) for value in counts)


def moment(counts: tuple[int, ...]) -> SPoly:
    name = atom_name(counts)
    return sc(1) if name == "1" else sv(name)


# ---------------------------------------------------------------------------
# Local random polynomials.  F_0 is the activation argument.  F_1,...,F_4
# and R are the only raw Gaussian coordinates which survive in the seven
# target contractions.
# ---------------------------------------------------------------------------


@dataclass(frozen=True, order=True)
class RMonomial:
    activation: tuple[int, ...]  # powers of phi^(0),...,phi^(5)
    forward: tuple[int, ...]     # powers of F_1,...,F_4
    reverse: int                 # power of R


RPoly = dict[RMonomial, SPoly]
RZERO = RMonomial((0,) * 6, (0,) * 4, 0)


def rc(value: int | Fraction) -> RPoly:
    scalar = sc(value)
    return {} if not scalar else {RZERO: scalar}


def r_from_scalar(value: Mapping[SMonomial, Fraction]) -> RPoly:
    return {} if not value else {RZERO: dict(value)}


def rg(kind: str, index: int = 0) -> RPoly:
    activation = [0] * 6
    forward = [0] * 4
    reverse = 0
    if kind == "p":
        activation[index] = 1
    elif kind == "f":
        if not 1 <= index <= 4:
            raise ValueError(index)
        forward[index - 1] = 1
    elif kind == "r":
        reverse = 1
    else:
        raise ValueError(kind)
    return {
        RMonomial(tuple(activation), tuple(forward), reverse): sc(1)
    }


def ra(*values: Mapping[RMonomial, SPoly]) -> RPoly:
    out: dict[RMonomial, SPoly] = {}
    for value in values:
        for monomial, coefficient in value.items():
            out[monomial] = sa(out.get(monomial, {}), coefficient)
            if not out[monomial]:
                del out[monomial]
    return out


def rs(value: Mapping[RMonomial, SPoly], factor: int | Fraction) -> RPoly:
    return {
        monomial: scaled
        for monomial, coefficient in value.items()
        if (scaled := ss(coefficient, factor))
    }


def rm(left: Mapping[RMonomial, SPoly], right: Mapping[RMonomial, SPoly]) -> RPoly:
    out: dict[RMonomial, SPoly] = {}
    for lm, lc in left.items():
        for rm_, rc_ in right.items():
            monomial = RMonomial(
                tuple(a + b for a, b in zip(lm.activation, rm_.activation)),
                tuple(a + b for a, b in zip(lm.forward, rm_.forward)),
                lm.reverse + rm_.reverse,
            )
            out[monomial] = sa(out.get(monomial, {}), sm(lc, rc_))
            if not out[monomial]:
                del out[monomial]
    return out


def rp(value: Mapping[RMonomial, SPoly], exponent: int) -> RPoly:
    if exponent < 0:
        raise ValueError("negative exponent")
    out = rc(1)
    base = dict(value)
    power = exponent
    while power:
        if power & 1:
            out = rm(out, base)
        power //= 2
        if power:
            base = rm(base, base)
    return out


def rproduct(*values: Mapping[RMonomial, SPoly]) -> RPoly:
    out = rc(1)
    for value in values:
        out = rm(out, value)
    return out


def r_derivative(value: Mapping[RMonomial, SPoly], kind: str) -> RPoly:
    if kind != "r":
        raise ValueError(kind)
    out: dict[RMonomial, SPoly] = {}
    for monomial, coefficient in value.items():
        if not monomial.reverse:
            continue
        target = RMonomial(
            monomial.activation,
            monomial.forward,
            monomial.reverse - 1,
        )
        out[target] = sa(
            out.get(target, {}), ss(coefficient, monomial.reverse)
        )
    return out


# Covariances of F_1,...,F_4.  Entries not listed vanish by parity.
U, V, W, X, Y, B = (sv(name) for name in ("u", "v", "w", "x", "y", "b"))
L1, L3, L5 = (sv(name) for name in ("l1", "l3", "l5"))


def covariance(i: int, j: int) -> SPoly:
    if i == 0 and j == 0:
        return sc(1)
    if i > j:
        i, j = j, i
    table: dict[tuple[int, int], SPoly] = {
        (0, 2): U,
        (0, 4): V,
        (1, 1): W,
        (1, 3): X,
        (2, 2): Y,
    }
    return table.get((i, j), {})


def activation_derivative(counts: tuple[int, ...]) -> list[tuple[int, tuple[int, ...]]]:
    out: list[tuple[int, tuple[int, ...]]] = []
    for derivative, count in enumerate(counts):
        if not count:
            continue
        if derivative == 5:
            raise RuntimeError("the proposed terminal recurrence generated phi^(6)")
        target = list(counts)
        target[derivative] -= 1
        target[derivative + 1] += 1
        out.append((count, tuple(target)))
    return out


@lru_cache(maxsize=None)
def wick_stein(monomial: RMonomial) -> SPoly:
    """Eliminate R and F_1,...,F_4 exactly, leaving one M atom."""

    if monomial.reverse:
        exponent = monomial.reverse
        if exponent & 1:
            return {}
        coefficient = 1
        for odd in range(1, exponent, 2):
            coefficient *= odd
        target = RMonomial(monomial.activation, monomial.forward, 0)
        return sproduct(sc(coefficient), sp(B, exponent // 2), wick_stein(target))

    first = next((index + 1 for index, power in enumerate(monomial.forward) if power), None)
    if first is None:
        return moment(monomial.activation)

    forward = list(monomial.forward)
    forward[first - 1] -= 1

    answer: SPoly = {}
    for other in range(first, 5):
        count = forward[other - 1]
        cov = covariance(first, other)
        if not count or not cov:
            continue
        paired = list(forward)
        paired[other - 1] -= 1
        target = RMonomial(monomial.activation, tuple(paired), 0)
        answer = sa(answer, sproduct(sc(count), cov, wick_stein(target)))

    cov0 = covariance(first, 0)
    if cov0:
        for count, activation in activation_derivative(monomial.activation):
            target = RMonomial(activation, tuple(forward), 0)
            answer = sa(answer, sproduct(sc(count), cov0, wick_stein(target)))
    return answer


def expectation(value: Mapping[RMonomial, SPoly]) -> SPoly:
    answer: SPoly = {}
    for monomial, coefficient in value.items():
        answer = sa(answer, sm(coefficient, wick_stein(monomial)))
    return answer


# ---------------------------------------------------------------------------
# Literal Bell polynomials and the seven contractions.
# ---------------------------------------------------------------------------


def local_forward_polynomials() -> list[RPoly]:
    p = [rg("p", r) for r in range(6)]
    f = [None] + [rg("f", r) for r in range(1, 5)]
    r = rg("r")
    delta = rm(p[1], r)

    z: list[RPoly] = [rc(0)] * 6
    z[1] = ra(f[1], rm(r_from_scalar(L1), delta))
    z[2] = f[2]
    z[3] = ra(f[3], rm(r_from_scalar(L3), delta))
    z[4] = f[4]
    # X_5 itself contains Z_5, but neither G_04 nor d_R X_5 needs the fresh
    # F_5 term.  Retaining only its R-dependent part is therefore exact for
    # all seven displayed states.
    z[5] = rm(r_from_scalar(L5), delta)

    x: list[RPoly] = [rc(0)] * 6
    x[0] = p[0]
    x[1] = rm(p[1], z[1])
    x[2] = ra(rproduct(p[2], z[1], z[1]), rm(p[1], z[2]))
    x[3] = ra(
        rproduct(p[3], z[1], z[1], z[1]),
        rs(rproduct(p[2], z[1], z[2]), 3),
        rm(p[1], z[3]),
    )
    x[4] = ra(
        rproduct(p[4], z[1], z[1], z[1], z[1]),
        rs(rproduct(p[3], z[1], z[1], z[2]), 6),
        rs(rproduct(p[2], z[2], z[2]), 3),
        rs(rproduct(p[2], z[1], z[3]), 4),
        rm(p[1], z[4]),
    )
    x[5] = ra(
        rproduct(p[5], z[1], z[1], z[1], z[1], z[1]),
        rs(rproduct(p[4], z[1], z[1], z[1], z[2]), 10),
        rs(rproduct(p[3], z[1], z[2], z[2]), 15),
        rs(rproduct(p[3], z[1], z[1], z[3]), 10),
        rs(rproduct(p[2], z[2], z[3]), 10),
        rs(rproduct(p[2], z[1], z[4]), 5),
        rm(p[1], z[5]),
    )
    return x


def transition() -> dict[str, SPoly]:
    x = local_forward_polynomials()
    return {
        "u_next": expectation(rm(x[0], x[2])),
        "v_next": expectation(rm(x[0], x[4])),
        "w_next": expectation(rm(x[1], x[1])),
        "x_next": expectation(rm(x[1], x[3])),
        "y_next": expectation(rm(x[2], x[2])),
        "j_next": expectation(r_derivative(x[3], "r")),
        "k_next": expectation(r_derivative(x[5], "r")),
    }


def _format_monomial(monomial: SMonomial) -> str:
    if not monomial:
        return "1"
    counts: dict[str, int] = {}
    for value in monomial:
        counts[value] = counts.get(value, 0) + 1
    return "*".join(
        name if power == 1 else f"{name}^{power}"
        for name, power in sorted(counts.items())
    )


def format_poly(value: Mapping[SMonomial, Fraction]) -> str:
    pieces: list[str] = []
    for monomial, coefficient in sorted(value.items(), key=lambda item: item[0]):
        body = _format_monomial(monomial)
        if body == "1":
            term = str(abs(coefficient))
        elif abs(coefficient) == 1:
            term = body
        else:
            term = f"{abs(coefficient)}*{body}"
        if not pieces:
            pieces.append(("-" if coefficient < 0 else "") + term)
        else:
            pieces.append((" - " if coefficient < 0 else " + ") + term)
    return "".join(pieces) if pieces else "0"


def serialise(value: Mapping[SMonomial, Fraction]) -> dict[str, str]:
    return {
        "*".join(monomial): (
            str(coefficient.numerator)
            if coefficient.denominator == 1
            else f"{coefficient.numerator}/{coefficient.denominator}"
        )
        for monomial, coefficient in sorted(value.items())
    }


def emit(directory: Path | None = None) -> dict[str, object]:
    directory = Path(__file__).resolve().parent if directory is None else directory
    result = transition()
    payload: dict[str, object] = {
        "contract": "independent frozen-line seven-scalar unit-Gram contraction",
        "state": ["u", "v", "w", "x", "y", "j", "k"],
        "lambdas": {
            "l1": "tau_(ell-1)",
            "l3": "j+3*u",
            "l5": "k+5*v",
        },
        "transition": {name: serialise(value) for name, value in result.items()},
        "formatted": {name: format_poly(value) for name, value in result.items()},
        "terminal": "straight_fifth = k_H + 5*v_H",
        "derivative_ceiling": max(
            max(
                index
                for index, count in enumerate(tuple(int(digit) for digit in name[1:]))
                if count
            )
            for value in result.values()
            for monomial in value
            for name in monomial
            if name.startswith("M")
        ),
    }
    encoded = json.dumps(payload, indent=2, sort_keys=True).encode()
    path = directory / "FROZEN_FORWARD_RECURRENCE.json"
    path.write_bytes(encoded + b"\n")
    digest = hashlib.sha256(path.read_bytes()).hexdigest()
    (directory / "FROZEN_FORWARD_RECURRENCE.sha256").write_text(
        digest + "  " + path.name + "\n"
    )
    return {"path": str(path), "sha256": digest, "payload": payload}


if __name__ == "__main__":
    emitted = emit()
    print(emitted["path"])
    print(emitted["sha256"])
    for name, formula in emitted["payload"]["formatted"].items():
        print(name, "=", formula)

"""Independent deterministic contraction of the moving-gradient sectors.

This module continues the frozen-line contraction without importing either
depth-order-five producer.  It uses four chronological scalar passes:

1. moving feature derivative two;
2. moving gradient derivative two;
3. moving feature derivative three;
4. moving gradient derivative three.

Together with ``forward_contraction`` and ``reverse_contraction`` these
passes evaluate the compact exact identity

    D^5 f = 2 S5 + 10 <A,C> + 10 <B,m2>
             + 4 <m2,m2> + 12 <A,m3>.

All local Gaussian variables below are derivation-only.  ``emit`` removes
them completely and freezes literal M-only scalar transition tables.
"""

from __future__ import annotations

from collections import defaultdict
from dataclasses import dataclass
from fractions import Fraction
from functools import lru_cache
import hashlib
import json
from pathlib import Path
from typing import Mapping

try:
    from .forward_contraction import (
        SMonomial, SPoly, format_poly, moment, sa, sc, serialise,
        sm, sproduct, ss, sv,
    )
except ImportError:
    from forward_contraction import (
        SMonomial, SPoly, format_poly, moment, sa, sc, serialise,
        sm, sproduct, ss, sv,
    )


@dataclass(frozen=True, order=True)
class RMonomial:
    activation: tuple[int, ...]
    forward: tuple[int, ...]  # F1,F2(frozen),F2(moving),F3(moving)
    reverse: tuple[int, ...]  # E0,E1,E2(frozen),E2(moving),E3(moving)


RPoly = dict[RMonomial, SPoly]
RZERO = RMonomial((0,) * 6, (0,) * 4, (0,) * 5)


def rc(value: int | Fraction) -> RPoly:
    coefficient = sc(value)
    return {} if not coefficient else {RZERO: coefficient}


def r_from_scalar(value: Mapping[SMonomial, Fraction]) -> RPoly:
    return {} if not value else {RZERO: dict(value)}


def rg(kind: str, index: int) -> RPoly:
    activation = [0] * 6
    forward = [0] * 4
    reverse = [0] * 5
    if kind == "p":
        activation[index] = 1
    elif kind == "f":
        forward[index - 1] = 1
    elif kind == "e":
        reverse[index] = 1
    else:
        raise ValueError(kind)
    return {RMonomial(tuple(activation), tuple(forward), tuple(reverse)): sc(1)}


def ra(*values: Mapping[RMonomial, SPoly]) -> RPoly:
    out: dict[RMonomial, SPoly] = {}
    for value in values:
        for monomial, coefficient in value.items():
            out[monomial] = sa(out.get(monomial, {}), coefficient)
            if not out[monomial]:
                del out[monomial]
    return out


def rs(value: Mapping[RMonomial, SPoly], factor: int | Fraction) -> RPoly:
    return {
        monomial: scaled
        for monomial, coefficient in value.items()
        if (scaled := ss(coefficient, factor))
    }


def rm(left: Mapping[RMonomial, SPoly], right: Mapping[RMonomial, SPoly]) -> RPoly:
    out: dict[RMonomial, SPoly] = {}
    for lm, lc in left.items():
        for rm_, rc_ in right.items():
            target = RMonomial(
                tuple(a + b for a, b in zip(lm.activation, rm_.activation)),
                tuple(a + b for a, b in zip(lm.forward, rm_.forward)),
                tuple(a + b for a, b in zip(lm.reverse, rm_.reverse)),
            )
            out[target] = sa(out.get(target, {}), sm(lc, rc_))
            if not out[target]:
                del out[target]
    return out


def rproduct(*values: Mapping[RMonomial, SPoly]) -> RPoly:
    out = rc(1)
    for value in values:
        out = rm(out, value)
    return out


def r_derivative(value: Mapping[RMonomial, SPoly], kind: str, index: int) -> RPoly:
    out: dict[RMonomial, SPoly] = {}
    for monomial, coefficient in value.items():
        if kind == "f":
            count = monomial.forward[index - 1]
            if not count:
                continue
            forward = list(monomial.forward)
            forward[index - 1] -= 1
            target = RMonomial(monomial.activation, tuple(forward), monomial.reverse)
            out[target] = sa(out.get(target, {}), ss(coefficient, count))
        elif kind == "e":
            count = monomial.reverse[index]
            if not count:
                continue
            reverse = list(monomial.reverse)
            reverse[index] -= 1
            target = RMonomial(monomial.activation, monomial.forward, tuple(reverse))
            out[target] = sa(out.get(target, {}), ss(coefficient, count))
        elif kind == "f0":
            for derivative, count in enumerate(monomial.activation):
                if not count:
                    continue
                if derivative == 5:
                    raise RuntimeError("phi^(6) generated")
                activation = list(monomial.activation)
                activation[derivative] -= 1
                activation[derivative + 1] += 1
                target = RMonomial(tuple(activation), monomial.forward, monomial.reverse)
                out[target] = sa(out.get(target, {}), ss(coefficient, count))
        else:
            raise ValueError((kind, index))
    return out


# Frozen forward inputs.
U, W, Y = (sv(name) for name in ("u", "w", "y"))
L1 = sv("l1")

# Frozen reverse inputs.
B = sv("b")
E02, E11, E22 = (sv(name) for name in ("e02", "e11", "e22"))
C10, C21 = sv("c10"), sv("c21")

# Moving feature-2 inputs.
Q02, Q22, QFM, A2 = (sv(name) for name in ("q02", "q22", "qfm", "a2"))
L2 = sv("l2")

# Moving reverse-2 inputs.
R02, R22, RFM, D21 = (sv(name) for name in ("r02", "r22", "rfm", "d21"))

# Moving feature-3 inputs.
Q13, A30, A32 = (sv(name) for name in ("q13", "a30", "a32"))
L30, L32 = sv("l30"), sv("l32")

# Moving reverse-3 inputs.
R13, D30, D32 = (sv(name) for name in ("r13", "d30", "d32"))


def forward_covariance(i: int, j: int) -> SPoly:
    if i == 0 and j == 0:
        return sc(1)
    if i > j:
        i, j = j, i
    table: dict[tuple[int, int], SPoly] = {
        (0, 2): U,
        (0, 3): Q02,
        (1, 1): W,
        (1, 4): Q13,
        (2, 2): Y,
        (2, 3): QFM,
        (3, 3): Q22,
    }
    return table.get((i, j), {})


def reverse_covariance(i: int, j: int) -> SPoly:
    if i > j:
        i, j = j, i
    table: dict[tuple[int, int], SPoly] = {
        (0, 0): B,
        (0, 2): E02,
        (0, 3): R02,
        (1, 1): E11,
        (1, 4): R13,
        (2, 2): E22,
        (2, 3): RFM,
        (3, 3): R22,
    }
    return table.get((i, j), {})


def activation_derivative(counts: tuple[int, ...]):
    for derivative, count in enumerate(counts):
        if not count:
            continue
        if derivative == 5:
            raise RuntimeError("phi^(6) generated by Wick--Stein")
        target = list(counts)
        target[derivative] -= 1
        target[derivative + 1] += 1
        yield count, tuple(target)


@lru_cache(maxsize=None)
def wick_stein(monomial: RMonomial) -> SPoly:
    first_reverse = next((i for i, power in enumerate(monomial.reverse) if power), None)
    if first_reverse is not None:
        reverse = list(monomial.reverse)
        reverse[first_reverse] -= 1
        answer: SPoly = {}
        for other in range(first_reverse, 5):
            count = reverse[other]
            cov = reverse_covariance(first_reverse, other)
            if not count or not cov:
                continue
            paired = list(reverse)
            paired[other] -= 1
            target = RMonomial(monomial.activation, monomial.forward, tuple(paired))
            answer = sa(answer, sproduct(sc(count), cov, wick_stein(target)))
        return answer

    first_forward = next((i + 1 for i, power in enumerate(monomial.forward) if power), None)
    if first_forward is None:
        return moment(monomial.activation)
    forward = list(monomial.forward)
    forward[first_forward - 1] -= 1
    answer = {}
    for other in range(first_forward, 5):
        count = forward[other - 1]
        cov = forward_covariance(first_forward, other)
        if not count or not cov:
            continue
        paired = list(forward)
        paired[other - 1] -= 1
        target = RMonomial(monomial.activation, tuple(paired), monomial.reverse)
        answer = sa(answer, sproduct(sc(count), cov, wick_stein(target)))
    cov0 = forward_covariance(first_forward, 0)
    if cov0:
        for count, activation in activation_derivative(monomial.activation):
            target = RMonomial(activation, tuple(forward), monomial.reverse)
            answer = sa(answer, sproduct(sc(count), cov0, wick_stein(target)))
    return answer


def expectation(value: Mapping[RMonomial, SPoly]) -> SPoly:
    answer: SPoly = {}
    for monomial, coefficient in value.items():
        answer = sa(answer, sm(coefficient, wick_stein(monomial)))
    return answer


def local_polynomials() -> dict[str, RPoly]:
    p = [rg("p", i) for i in range(6)]
    f1, f2, g2, g3 = (rg("f", i) for i in range(1, 5))
    e0, e1, e2, j2, j3 = (rg("e", i) for i in range(5))

    d0 = rm(p[1], e0)
    z1 = ra(f1, rm(r_from_scalar(L1), d0))
    x0 = p[0]
    x1 = rm(p[1], z1)
    x2 = ra(rproduct(p[2], z1, z1), rm(p[1], f2))

    r1 = ra(e1, rm(r_from_scalar(C10), x0))
    d1 = ra(rproduct(p[2], z1, e0), rm(p[1], r1))

    z2 = ra(g2, rm(r_from_scalar(L2), d1))
    h2 = ra(rproduct(p[2], z1, z1), rm(p[1], z2))

    r2f = ra(e2, rm(r_from_scalar(C21), x1))
    d2f = ra(
        rproduct(p[3], z1, z1, e0), rproduct(p[2], f2, e0),
        rs(rproduct(p[2], z1, r1), 2), rm(p[1], r2f),
    )

    r2m = ra(j2, rm(r_from_scalar(D21), x1))
    d2m = ra(
        rproduct(p[3], z1, z1, e0), rproduct(p[2], z2, e0),
        rs(rproduct(p[2], z1, r1), 2), rm(p[1], r2m),
    )

    z3 = ra(g3, rm(r_from_scalar(L30), d0), rm(r_from_scalar(L32), d2m))
    h3 = ra(
        rproduct(p[3], z1, z1, z1),
        rs(rproduct(p[2], z1, z2), 3),
        rm(p[1], z3),
    )

    r3m = ra(j3, rm(r_from_scalar(D30), x0), rm(r_from_scalar(D32), h2))
    d3m = ra(
        rproduct(p[4], z1, z1, z1, e0),
        rs(rproduct(p[3], z1, z2, e0), 3),
        rproduct(p[2], z3, e0),
        rs(rproduct(p[3], z1, z1, r1), 3),
        rs(rproduct(p[2], z2, r1), 3),
        rs(rproduct(p[2], z1, r2m), 3),
        rm(p[1], r3m),
    )
    return {
        "x0": x0, "x1": x1, "x2": x2,
        "d0": d0, "d1": d1, "d2f": d2f,
        "h2": h2, "d2m": d2m, "h3": h3, "d3m": d3m,
    }


def transitions() -> dict[str, dict[str, SPoly]]:
    q = local_polynomials()
    source00 = expectation(rm(q["d0"], q["d0"]))
    source11 = expectation(rm(q["d1"], q["d1"]))
    source02m = expectation(rm(q["d0"], q["d2m"]))
    return {
        "feature2": {
            "q02_next": expectation(rm(q["x0"], q["h2"])),
            "q22_next": expectation(rm(q["h2"], q["h2"])),
            "qfm_next": expectation(rm(q["x2"], q["h2"])),
            "a2_next": expectation(r_derivative(q["h2"], "e", 1)),
        },
        "gradient2": {
            "source02m": source02m,
            "source22m": expectation(rm(q["d2m"], q["d2m"])),
            "sourcefm": expectation(rm(q["d2f"], q["d2m"])),
            "r02_next": source02m,
            "r22_next": expectation(rm(q["d2m"], q["d2m"])),
            "rfm_next": expectation(rm(q["d2f"], q["d2m"])),
            "d21_next": sa(source00, expectation(r_derivative(q["d2m"], "f", 1))),
        },
        "feature3": {
            "q13_next": expectation(rm(q["x1"], q["h3"])),
            "a30_next": expectation(r_derivative(q["h3"], "e", 0)),
            "a32_next": expectation(r_derivative(q["h3"], "e", 3)),
        },
        "gradient3": {
            "source13m": expectation(rm(q["d1"], q["d3m"])),
            "r13_next": expectation(rm(q["d1"], q["d3m"])),
            "d30_next": sa(
                ss(source02m, 4), ss(source11, 3),
                expectation(r_derivative(q["d3m"], "f0", 0)),
            ),
            "d32_next": sa(
                source00, expectation(r_derivative(q["d3m"], "f", 3)),
            ),
        },
    }


def emit(directory: Path | None = None) -> dict[str, object]:
    directory = Path(__file__).resolve().parent if directory is None else directory
    result = transitions()
    payload: dict[str, object] = {
        "contract": "independent four-pass moving-gradient scalar contraction",
        "states": {
            "feature2": ["q02", "q22", "qfm", "a2"],
            "gradient2": ["r02", "r22", "rfm", "d21"],
            "feature3": ["q13", "a30", "a32"],
            "gradient3": ["r13", "d30", "d32"],
        },
        "transition": {
            group: {name: serialise(poly) for name, poly in values.items()}
            for group, values in result.items()
        },
        "formatted": {
            group: {name: format_poly(poly) for name, poly in values.items()}
            for group, values in result.items()
        },
    }
    path = directory / "FROZEN_MOVING_RECURRENCE.json"
    path.write_text(json.dumps(payload, indent=2, sort_keys=True) + "\n")
    digest = hashlib.sha256(path.read_bytes()).hexdigest()
    (directory / "FROZEN_MOVING_RECURRENCE.sha256").write_text(
        digest + "  " + path.name + "\n"
    )
    markdown = directory / "FROZEN_MOVING_TRANSITIONS.md"
    lines = [
        "# Explicit contracted moving-gradient transitions", "",
        "Generated from `moving_contraction.py`. Every right-hand side is a",
        "finite deterministic polynomial in M-atoms and prior scalar states.", "",
    ]
    for group, values in payload["formatted"].items():
        lines.extend((f"# {group}", ""))
        for name, formula in values.items():
            lines.extend((f"## `{name}`", "", "```text", f"{name} = {formula}", "```", ""))
    markdown.write_text("\n".join(lines))
    markdown_digest = hashlib.sha256(markdown.read_bytes()).hexdigest()
    (directory / "FROZEN_MOVING_TRANSITIONS.sha256").write_text(
        markdown_digest + "  " + markdown.name + "\n"
    )
    return {
        "path": str(path), "sha256": digest,
        "markdown": str(markdown), "markdown_sha256": markdown_digest,
        "payload": payload,
    }


if __name__ == "__main__":
    result = emit()
    print(result["path"])
    print(result["sha256"])
    for group, values in result["payload"]["formatted"].items():
        print("[", group, "]")
        for name, formula in values.items():
            print(name, "=", formula)

"""Independent Wick--Stein contraction of the hidden-feature Gamma_04 head.

This route was derived from the exact feature-ascent product rule and the
already frozen universal F1/R1/F2/R2/F3/R3 backbone.  It does not import a
competing Gamma_04 producer.  ``emit`` removes every derivation-only Gaussian
and writes literal deterministic M-only transition polynomials.
"""

from __future__ import annotations

from collections import defaultdict
from dataclasses import dataclass
from fractions import Fraction
from functools import lru_cache
import hashlib
import json
from pathlib import Path
from typing import Mapping

from ...independent.forward_contraction import (
    SMonomial,
    SPoly,
    format_poly,
    moment,
    sa,
    sc,
    serialise,
    sm,
    sproduct,
    ss,
    sv,
)


@dataclass(frozen=True, order=True)
class RMonomial:
    activation: tuple[int, ...]
    # f1, frozen-f2, moving-f2, moving-f3, moving-f4
    forward: tuple[int, ...]
    # e0, e1, frozen-e2, moving-e2, moving-e3
    reverse: tuple[int, ...]


RPoly = dict[RMonomial, SPoly]
RZERO = RMonomial((0,) * 6, (0,) * 5, (0,) * 5)


def rc(value: int | Fraction) -> RPoly:
    coefficient = sc(value)
    return {} if not coefficient else {RZERO: coefficient}


def r_from_scalar(value: Mapping[SMonomial, Fraction]) -> RPoly:
    return {} if not value else {RZERO: dict(value)}


def rg(kind: str, index: int) -> RPoly:
    activation = [0] * 6
    forward = [0] * 5
    reverse = [0] * 5
    if kind == "p":
        activation[index] = 1
    elif kind == "f":
        forward[index - 1] = 1
    elif kind == "e":
        reverse[index] = 1
    else:
        raise ValueError(kind)
    return {
        RMonomial(tuple(activation), tuple(forward), tuple(reverse)): sc(1)
    }


def ra(*values: Mapping[RMonomial, SPoly]) -> RPoly:
    out: dict[RMonomial, SPoly] = {}
    for value in values:
        for monomial, coefficient in value.items():
            out[monomial] = sa(out.get(monomial, {}), coefficient)
            if not out[monomial]:
                del out[monomial]
    return out


def rs(value: Mapping[RMonomial, SPoly], factor: int | Fraction) -> RPoly:
    return {
        monomial: scaled
        for monomial, coefficient in value.items()
        if (scaled := ss(coefficient, factor))
    }


def rm(left: Mapping[RMonomial, SPoly], right: Mapping[RMonomial, SPoly]) -> RPoly:
    out: dict[RMonomial, SPoly] = {}
    for left_monomial, left_coefficient in left.items():
        for right_monomial, right_coefficient in right.items():
            target = RMonomial(
                tuple(
                    a + b
                    for a, b in zip(
                        left_monomial.activation, right_monomial.activation
                    )
                ),
                tuple(
                    a + b
                    for a, b in zip(
                        left_monomial.forward, right_monomial.forward
                    )
                ),
                tuple(
                    a + b
                    for a, b in zip(
                        left_monomial.reverse, right_monomial.reverse
                    )
                ),
            )
            out[target] = sa(
                out.get(target, {}), sm(left_coefficient, right_coefficient)
            )
            if not out[target]:
                del out[target]
    return out


def rproduct(*values: Mapping[RMonomial, SPoly]) -> RPoly:
    out = rc(1)
    for value in values:
        out = rm(out, value)
    return out


def r_derivative(value: Mapping[RMonomial, SPoly], kind: str, index: int) -> RPoly:
    out: dict[RMonomial, SPoly] = {}
    for monomial, coefficient in value.items():
        if kind == "e":
            count = monomial.reverse[index]
            if not count:
                continue
            reverse = list(monomial.reverse)
            reverse[index] -= 1
            target = RMonomial(monomial.activation, monomial.forward, tuple(reverse))
            out[target] = sa(out.get(target, {}), ss(coefficient, count))
        else:
            raise ValueError((kind, index))
    return out


# Frozen universal-backbone inputs at the preceding/current layer.
U, W, Y = (sv(name) for name in ("u", "w", "y"))
Q02, Q22, QFM = (sv(name) for name in ("q02", "q22", "qfm"))
Q13, Q04 = sv("q13"), sv("gamma04")
B = sv("b")
E02, E11, E22 = (sv(name) for name in ("e02", "e11", "e22"))
C10, C21 = sv("c10"), sv("c21")
R02, R22, RFM, D21 = (sv(name) for name in ("r02", "r22", "rfm", "d21"))
R13, D30, D32 = (sv(name) for name in ("r13", "d30", "d32"))

# Deterministic response coefficients used in the current local map.
L1, L2, L30, L32, L41, L43 = (
    sv(name) for name in ("l1", "l2", "l30", "l32", "l41", "l43")
)


def forward_covariance(i: int, j: int) -> SPoly:
    if i == 0 and j == 0:
        return sc(1)
    if i > j:
        i, j = j, i
    table: dict[tuple[int, int], SPoly] = {
        (0, 2): U,
        (0, 3): Q02,
        (0, 5): Q04,
        (1, 1): W,
        (1, 4): Q13,
        (2, 2): Y,
        (2, 3): QFM,
        (3, 3): Q22,
    }
    return table.get((i, j), {})


def reverse_covariance(i: int, j: int) -> SPoly:
    if i > j:
        i, j = j, i
    table: dict[tuple[int, int], SPoly] = {
        (0, 0): B,
        (0, 2): E02,
        (0, 3): R02,
        (1, 1): E11,
        (1, 4): R13,
        (2, 2): E22,
        (2, 3): RFM,
        (3, 3): R22,
    }
    return table.get((i, j), {})


def activation_derivative(counts: tuple[int, ...]):
    for derivative, count in enumerate(counts):
        if not count:
            continue
        if derivative == 5:
            raise RuntimeError("phi^(6) generated")
        target = list(counts)
        target[derivative] -= 1
        target[derivative + 1] += 1
        yield count, tuple(target)


@lru_cache(maxsize=None)
def wick_stein(monomial: RMonomial) -> SPoly:
    first_reverse = next(
        (i for i, power in enumerate(monomial.reverse) if power), None
    )
    if first_reverse is not None:
        reverse = list(monomial.reverse)
        reverse[first_reverse] -= 1
        answer: SPoly = {}
        for other in range(first_reverse, 5):
            count = reverse[other]
            covariance = reverse_covariance(first_reverse, other)
            if not count or not covariance:
                continue
            paired = list(reverse)
            paired[other] -= 1
            target = RMonomial(
                monomial.activation, monomial.forward, tuple(paired)
            )
            answer = sa(
                answer,
                sproduct(sc(count), covariance, wick_stein(target)),
            )
        return answer

    first_forward = next(
        (i + 1 for i, power in enumerate(monomial.forward) if power), None
    )
    if first_forward is None:
        return moment(monomial.activation)

    forward = list(monomial.forward)
    forward[first_forward - 1] -= 1
    answer: SPoly = {}
    for other in range(first_forward, 6):
        count = forward[other - 1]
        covariance = forward_covariance(first_forward, other)
        if not count or not covariance:
            continue
        paired = list(forward)
        paired[other - 1] -= 1
        target = RMonomial(
            monomial.activation, tuple(paired), monomial.reverse
        )
        answer = sa(
            answer,
            sproduct(sc(count), covariance, wick_stein(target)),
        )

    covariance0 = forward_covariance(first_forward, 0)
    if covariance0:
        for count, activation in activation_derivative(monomial.activation):
            target = RMonomial(
                activation, tuple(forward), monomial.reverse
            )
            answer = sa(
                answer,
                sproduct(sc(count), covariance0, wick_stein(target)),
            )
    return answer


def expectation(value: Mapping[RMonomial, SPoly]) -> SPoly:
    answer: SPoly = {}
    for monomial, coefficient in value.items():
        answer = sa(answer, sm(coefficient, wick_stein(monomial)))
    return answer


def local_polynomials() -> dict[str, RPoly]:
    p = [rg("p", i) for i in range(6)]
    f1, f2, g2, g3, g4 = (rg("f", i) for i in range(1, 6))
    e0, e1, e2, j2, j3 = (rg("e", i) for i in range(5))

    d0 = rm(p[1], e0)
    z1 = ra(f1, rm(r_from_scalar(L1), d0))
    x0 = p[0]
    x1 = rm(p[1], z1)
    x2 = ra(rproduct(p[2], z1, z1), rm(p[1], f2))

    r1 = ra(e1, rm(r_from_scalar(C10), x0))
    d1 = ra(rproduct(p[2], z1, e0), rm(p[1], r1))

    z2 = ra(g2, rm(r_from_scalar(L2), d1))
    h2 = ra(rproduct(p[2], z1, z1), rm(p[1], z2))

    r2m = ra(j2, rm(r_from_scalar(D21), x1))
    d2m = ra(
        rproduct(p[3], z1, z1, e0),
        rproduct(p[2], z2, e0),
        rs(rproduct(p[2], z1, r1), 2),
        rm(p[1], r2m),
    )

    z3 = ra(g3, rm(r_from_scalar(L30), d0), rm(r_from_scalar(L32), d2m))
    h3 = ra(
        rproduct(p[3], z1, z1, z1),
        rs(rproduct(p[2], z1, z2), 3),
        rm(p[1], z3),
    )

    r3m = ra(j3, rm(r_from_scalar(D30), x0), rm(r_from_scalar(D32), h2))
    d3m = ra(
        rproduct(p[4], z1, z1, z1, e0),
        rs(rproduct(p[3], z1, z2, e0), 3),
        rproduct(p[2], z3, e0),
        rs(rproduct(p[3], z1, z1, r1), 3),
        rs(rproduct(p[2], z2, r1), 3),
        rs(rproduct(p[2], z1, r2m), 3),
        rm(p[1], r3m),
    )

    z4 = ra(g4, rm(r_from_scalar(L41), d1), rm(r_from_scalar(L43), d3m))
    h4 = ra(
        rproduct(p[4], z1, z1, z1, z1),
        rs(rproduct(p[3], z1, z1, z2), 6),
        rs(rproduct(p[2], z2, z2), 3),
        rs(rproduct(p[2], z1, z3), 4),
        rm(p[1], z4),
    )
    return {
        "x0": x0,
        "x1": x1,
        "h2": h2,
        "h3": h3,
        "h4": h4,
        "z1": z1,
        "z2": z2,
        "z3": z3,
        "z4": z4,
        "d1": d1,
        "d3m": d3m,
    }


def transitions() -> dict[str, SPoly]:
    q = local_polynomials()
    return {
        "gamma04_next": expectation(rm(q["x0"], q["h4"])),
        "a41_next": expectation(r_derivative(q["h4"], "e", 1)),
        "a43_next": expectation(r_derivative(q["h4"], "e", 4)),
    }


def emit(directory: Path | None = None) -> dict[str, object]:
    directory = Path(__file__).resolve().parent if directory is None else directory
    result = transitions()
    payload: dict[str, object] = {
        "contract": "independent post-R3 hidden-feature Gamma_04 contraction",
        "state": ["gamma04", "a41", "a43"],
        "initial_state": {"gamma04": 0, "a41": 0, "a43": 0},
        "layer_coefficients": {
            "l41": "9*q02 + 8*w + a41",
            "l43": "1 + a43",
        },
        "transition": {
            name: serialise(polynomial) for name, polynomial in result.items()
        },
        "formatted": {
            name: format_poly(polynomial) for name, polynomial in result.items()
        },
    }
    path = directory / "FROZEN_GAMMA04_RECURRENCE.json"
    path.write_text(json.dumps(payload, indent=2, sort_keys=True) + "\n")
    digest = hashlib.sha256(path.read_bytes()).hexdigest()
    (directory / "FROZEN_GAMMA04_RECURRENCE.sha256").write_text(
        digest + "  " + path.name + "\n"
    )

    markdown = directory / "FROZEN_GAMMA04_TRANSITIONS.md"
    lines = [
        "# Frozen independent Gamma_04 transition",
        "",
        "Every right-hand side below is a deterministic polynomial in declared",
        "one-dimensional M-atoms and previously computed scalar states.",
        "",
    ]
    for name, formula in payload["formatted"].items():
        lines.extend(
            (
                f"## `{name}`",
                "",
                "```text",
                f"{name} = {formula}",
                "```",
                "",
            )
        )
    markdown.write_text("\n".join(lines))
    markdown_digest = hashlib.sha256(markdown.read_bytes()).hexdigest()
    (directory / "FROZEN_GAMMA04_TRANSITIONS.sha256").write_text(
        markdown_digest + "  " + markdown.name + "\n"
    )
    return {
        "path": str(path),
        "sha256": digest,
        "markdown": str(markdown),
        "markdown_sha256": markdown_digest,
        "payload": payload,
    }


if __name__ == "__main__":
    emitted = emit()
    print(emitted["path"])
    print(emitted["sha256"])
    print(emitted["markdown"])
    print(emitted["markdown_sha256"])

"""Independent local Wick--Stein contraction for the moving ``Gamma_04`` head.

This file was written and frozen before any competing ``Gamma_04`` formula
was inspected.  It imports only the scalar-polynomial alphabet used by the
already frozen feature-ascent backbone.  The local Gaussian variables in this
source are derivation scaffolding: :func:`emit` removes all of them and writes
three literal M-only transition polynomials.

The three head states are ordinary-derivative quantities

    gamma04 = E[X_0 X_4],
    a41     = E[d X_4 / d E_1],
    a43     = E[d X_4 / d J_3].

No claim of dimension minimality is made.
"""

from __future__ import annotations

from collections import defaultdict
from dataclasses import dataclass
from fractions import Fraction
from functools import lru_cache
import hashlib
import json
from pathlib import Path
from typing import Mapping

from ...depth_order5_scalar.independent.forward_contraction import (
    SMonomial,
    SPoly,
    format_poly,
    moment,
    sa,
    sc,
    serialise,
    sm,
    sproduct,
    ss,
    sv,
)


@dataclass(frozen=True, order=True)
class LocalMonomial:
    activation: tuple[int, ...]
    forward: tuple[int, ...]  # F1,F2(frozen),F2,F3,F4(moving)
    reverse: tuple[int, ...]  # E0,E1,E2(frozen),E2,E3(moving)


LocalPoly = dict[LocalMonomial, SPoly]
ZERO = LocalMonomial((0,) * 6, (0,) * 5, (0,) * 5)


def lc(value: int | Fraction) -> LocalPoly:
    coefficient = sc(value)
    return {} if not coefficient else {ZERO: coefficient}


def lscalar(value: Mapping[SMonomial, Fraction]) -> LocalPoly:
    return {} if not value else {ZERO: dict(value)}


def lg(kind: str, index: int) -> LocalPoly:
    activation = [0] * 6
    forward = [0] * 5
    reverse = [0] * 5
    if kind == "p":
        activation[index] = 1
    elif kind == "f":
        forward[index - 1] = 1
    elif kind == "e":
        reverse[index] = 1
    else:
        raise ValueError(kind)
    return {
        LocalMonomial(tuple(activation), tuple(forward), tuple(reverse)): sc(1)
    }


def la(*values: Mapping[LocalMonomial, SPoly]) -> LocalPoly:
    out: dict[LocalMonomial, SPoly] = {}
    for value in values:
        for monomial, coefficient in value.items():
            out[monomial] = sa(out.get(monomial, {}), coefficient)
            if not out[monomial]:
                del out[monomial]
    return out


def ls(value: Mapping[LocalMonomial, SPoly], factor: int | Fraction) -> LocalPoly:
    return {
        monomial: scaled
        for monomial, coefficient in value.items()
        if (scaled := ss(coefficient, factor))
    }


def lm(
    left: Mapping[LocalMonomial, SPoly],
    right: Mapping[LocalMonomial, SPoly],
) -> LocalPoly:
    out: dict[LocalMonomial, SPoly] = {}
    for left_monomial, left_coefficient in left.items():
        for right_monomial, right_coefficient in right.items():
            target = LocalMonomial(
                tuple(
                    x + y
                    for x, y in zip(
                        left_monomial.activation, right_monomial.activation
                    )
                ),
                tuple(
                    x + y
                    for x, y in zip(left_monomial.forward, right_monomial.forward)
                ),
                tuple(
                    x + y
                    for x, y in zip(left_monomial.reverse, right_monomial.reverse)
                ),
            )
            out[target] = sa(
                out.get(target, {}), sm(left_coefficient, right_coefficient)
            )
            if not out[target]:
                del out[target]
    return out


def lproduct(*values: Mapping[LocalMonomial, SPoly]) -> LocalPoly:
    out = lc(1)
    for value in values:
        out = lm(out, value)
    return out


def lpower(value: Mapping[LocalMonomial, SPoly], power: int) -> LocalPoly:
    out = lc(1)
    for _ in range(power):
        out = lm(out, value)
    return out


def lderivative(
    value: Mapping[LocalMonomial, SPoly], kind: str, index: int
) -> LocalPoly:
    out: dict[LocalMonomial, SPoly] = {}
    for monomial, coefficient in value.items():
        if kind != "e":
            raise ValueError(kind)
        count = monomial.reverse[index]
        if not count:
            continue
        reverse = list(monomial.reverse)
        reverse[index] -= 1
        target = LocalMonomial(monomial.activation, monomial.forward, tuple(reverse))
        out[target] = sa(out.get(target, {}), ss(coefficient, count))
    return out


# Frozen backbone scalar inputs at the lower layer / current reverse layer.
U, W = (sv(name) for name in ("u", "w"))
Q02, Q22, QFM = (sv(name) for name in ("q02", "q22", "qfm"))
Q13, Q04 = (sv(name) for name in ("q13", "gamma04"))
B = sv("b")
E02, E11, E22 = (sv(name) for name in ("e02", "e11", "e22"))
C10, C21 = sv("c10"), sv("c21")
R02, R22, RFM, D21 = (sv(name) for name in ("r02", "r22", "rfm", "d21"))
R13, D30, D32 = (sv(name) for name in ("r13", "d30", "d32"))

L1, L2 = sv("l1"), sv("l2")
L30, L32 = sv("l30"), sv("l32")
L41, L43 = sv("l41"), sv("l43")


def forward_covariance(i: int, j: int) -> SPoly:
    if i == 0 and j == 0:
        return sc(1)
    if i > j:
        i, j = j, i
    table: dict[tuple[int, int], SPoly] = {
        (0, 2): U,
        (0, 3): Q02,
        (0, 5): Q04,
        (1, 1): W,
        (1, 4): Q13,
        (2, 2): sv("y"),
        (2, 3): QFM,
        (3, 3): Q22,
    }
    return table.get((i, j), {})


def reverse_covariance(i: int, j: int) -> SPoly:
    if i > j:
        i, j = j, i
    table: dict[tuple[int, int], SPoly] = {
        (0, 0): B,
        (0, 2): E02,
        (0, 3): R02,
        (1, 1): E11,
        (1, 4): R13,
        (2, 2): E22,
        (2, 3): RFM,
        (3, 3): R22,
    }
    return table.get((i, j), {})


def activation_derivative(counts: tuple[int, ...]):
    for derivative, count in enumerate(counts):
        if not count:
            continue
        if derivative == 5:
            raise RuntimeError("phi^(6) generated by Gamma_04 Wick--Stein")
        target = list(counts)
        target[derivative] -= 1
        target[derivative + 1] += 1
        yield count, tuple(target)


@lru_cache(maxsize=None)
def wick_stein(monomial: LocalMonomial) -> SPoly:
    """Eliminate all reverse Gaussians by Wick, then all forward by Stein."""

    first_reverse = next(
        (i for i, power in enumerate(monomial.reverse) if power), None
    )
    if first_reverse is not None:
        reverse = list(monomial.reverse)
        reverse[first_reverse] -= 1
        answer: SPoly = {}
        for other in range(first_reverse, len(reverse)):
            count = reverse[other]
            covariance = reverse_covariance(first_reverse, other)
            if not count or not covariance:
                continue
            paired = list(reverse)
            paired[other] -= 1
            target = LocalMonomial(
                monomial.activation, monomial.forward, tuple(paired)
            )
            answer = sa(
                answer,
                sproduct(sc(count), covariance, wick_stein(target)),
            )
        return answer

    first_forward = next(
        (i + 1 for i, power in enumerate(monomial.forward) if power), None
    )
    if first_forward is None:
        return moment(monomial.activation)

    forward = list(monomial.forward)
    forward[first_forward - 1] -= 1
    answer: SPoly = {}
    for other in range(first_forward, len(forward) + 1):
        count = forward[other - 1]
        covariance = forward_covariance(first_forward, other)
        if not count or not covariance:
            continue
        paired = list(forward)
        paired[other - 1] -= 1
        target = LocalMonomial(monomial.activation, tuple(paired), monomial.reverse)
        answer = sa(
            answer,
            sproduct(sc(count), covariance, wick_stein(target)),
        )

    covariance0 = forward_covariance(first_forward, 0)
    if covariance0:
        for count, activation in activation_derivative(monomial.activation):
            target = LocalMonomial(activation, tuple(forward), monomial.reverse)
            answer = sa(
                answer,
                sproduct(sc(count), covariance0, wick_stein(target)),
            )
    return answer


def expectation(value: Mapping[LocalMonomial, SPoly]) -> SPoly:
    answer: SPoly = {}
    for monomial, coefficient in value.items():
        answer = sa(answer, sm(coefficient, wick_stein(monomial)))
    return answer


def local_polynomials() -> dict[str, LocalPoly]:
    """Return the complete ordinary-derivative local feature skeleton."""

    p = [lg("p", i) for i in range(6)]
    f1, f2, g2, g3, g4 = (lg("f", i) for i in range(1, 6))
    e0, e1, e2, j2, j3 = (lg("e", i) for i in range(5))

    d0 = lm(p[1], e0)
    z1 = la(f1, lm(lscalar(L1), d0))
    x0 = p[0]
    x1 = lm(p[1], z1)
    x2 = la(lproduct(p[2], z1, z1), lm(p[1], f2))

    r1 = la(e1, lm(lscalar(C10), x0))
    d1 = la(lproduct(p[2], z1, e0), lm(p[1], r1))

    z2 = la(g2, lm(lscalar(L2), d1))
    h2 = la(lproduct(p[2], z1, z1), lm(p[1], z2))

    r2f = la(e2, lm(lscalar(C21), x1))
    d2f = la(
        lproduct(p[3], z1, z1, e0),
        lproduct(p[2], f2, e0),
        ls(lproduct(p[2], z1, r1), 2),
        lm(p[1], r2f),
    )

    r2m = la(j2, lm(lscalar(D21), x1))
    d2m = la(
        lproduct(p[3], z1, z1, e0),
        lproduct(p[2], z2, e0),
        ls(lproduct(p[2], z1, r1), 2),
        lm(p[1], r2m),
    )

    z3 = la(g3, lm(lscalar(L30), d0), lm(lscalar(L32), d2m))
    h3 = la(
        lproduct(p[3], z1, z1, z1),
        ls(lproduct(p[2], z1, z2), 3),
        lm(p[1], z3),
    )

    r3m = la(j3, lm(lscalar(D30), x0), lm(lscalar(D32), h2))
    d3m = la(
        lproduct(p[4], z1, z1, z1, e0),
        ls(lproduct(p[3], z1, z2, e0), 3),
        lproduct(p[2], z3, e0),
        ls(lproduct(p[3], z1, z1, r1), 3),
        ls(lproduct(p[2], z2, r1), 3),
        ls(lproduct(p[2], z1, r2m), 3),
        lm(p[1], r3m),
    )

    # Complete fourth ordinary derivative.  The 1,6,3,4,1 coefficients are
    # the five equality partitions of four in Faà di Bruno form.
    z4 = la(g4, lm(lscalar(L41), d1), lm(lscalar(L43), d3m))
    h4 = la(
        lproduct(p[4], z1, z1, z1, z1),
        ls(lproduct(p[3], z1, z1, z2), 6),
        ls(lproduct(p[2], z2, z2), 3),
        ls(lproduct(p[2], z1, z3), 4),
        lm(p[1], z4),
    )

    return {
        "x0": x0,
        "x1": x1,
        "x2": x2,
        "h2": h2,
        "h3": h3,
        "h4": h4,
        "d0": d0,
        "d1": d1,
        "d2f": d2f,
        "d2m": d2m,
        "d3m": d3m,
    }


def transitions() -> dict[str, SPoly]:
    local = local_polynomials()
    return {
        "gamma04_next": expectation(lm(local["x0"], local["h4"])),
        "a41_next": expectation(lderivative(local["h4"], "e", 1)),
        "a43_next": expectation(lderivative(local["h4"], "e", 4)),
    }


def local_audit() -> dict[str, object]:
    local = local_polynomials()
    raw_h4_terms = len(local["h4"])
    raw_partition_coefficients: dict[str, int] = defaultdict(int)
    # The explicit identity is deliberately recorded independently of the
    # contracted output so a later edit cannot silently drop a family.
    for name, coefficient in (
        ("phi4_z1^4", 1),
        ("phi3_z1^2_z2", 6),
        ("phi2_z2^2", 3),
        ("phi2_z1_z3", 4),
        ("phi1_z4", 1),
    ):
        raw_partition_coefficients[name] = coefficient
    contracted = transitions()
    # ``SPoly`` keys contain only terminal scalar symbol names.  The local
    # Gaussian exponents live in ``LocalMonomial`` and cannot be represented
    # in this terminal type at all.
    forbidden_prefixes = ("F", "R", "E", "J")
    residual_local_monomials = {
        name: sum(
            1
            for monomial in polynomial
            if any(symbol.startswith(forbidden_prefixes) for symbol in monomial)
        )
        for name, polynomial in contracted.items()
    }
    maximum_derivative = 0
    for polynomial in contracted.values():
        for monomial in polynomial:
            for atom_name in monomial:
                if atom_name.startswith("M"):
                    digits = atom_name[1:]
                    for derivative, count in enumerate(digits):
                        if count != "0":
                            maximum_derivative = max(maximum_derivative, derivative)
    return {
        "raw_h4_local_monomials": raw_h4_terms,
        "equality_partition_coefficients": dict(raw_partition_coefficients),
        "contracted_term_counts": {
            name: len(polynomial) for name, polynomial in contracted.items()
        },
        "residual_local_gaussian_monomials": residual_local_monomials,
        "maximum_activation_derivative": maximum_derivative,
    }


def emit(directory: Path | None = None) -> dict[str, object]:
    directory = Path(__file__).resolve().parent if directory is None else directory
    result = transitions()
    payload: dict[str, object] = {
        "contract": "independent one-pass moving Gamma_04 scalar head",
        "state": ["gamma04", "a41", "a43"],
        "initialization": {"gamma04": 0, "a41": 0, "a43": 0},
        "derived_abbreviations": {
            "l41": "9*q02 + 8*w + a41",
            "l43": "1 + a43",
        },
        "transition": {
            name: serialise(polynomial) for name, polynomial in result.items()
        },
        "formatted": {
            name: format_poly(polynomial) for name, polynomial in result.items()
        },
        "local_audit": local_audit(),
    }
    path = directory / "FROZEN_GAMMA04_RECURRENCE.json"
    path.write_text(json.dumps(payload, indent=2, sort_keys=True) + "\n")
    digest = hashlib.sha256(path.read_bytes()).hexdigest()
    formula_path = directory / "FROZEN_GAMMA04_TRANSITIONS.md"
    lines = [
        "# Frozen independent `Gamma_04` transitions",
        "",
        "Every right-hand side is a literal deterministic polynomial in",
        "one-dimensional `M` atoms and prior scalar states.",
        "",
    ]
    for name, formula in payload["formatted"].items():
        lines.extend((f"## `{name}`", "", "```text", f"{name} = {formula}", "```", ""))
    formula_path.write_text("\n".join(lines))
    formula_digest = hashlib.sha256(formula_path.read_bytes()).hexdigest()
    return {
        "path": str(path),
        "sha256": digest,
        "formula_path": str(formula_path),
        "formula_sha256": formula_digest,
        "payload": payload,
    }


if __name__ == "__main__":
    emitted = emit()
    print(emitted["path"])
    print(emitted["sha256"])
    print(emitted["formula_path"])
    print(emitted["formula_sha256"])
    print(json.dumps(emitted["payload"]["local_audit"], indent=2, sort_keys=True))

"""Hostile, derivation-independent exact checks for the order-five package.

This file is deliberately outside both coefficient compilers.  It uses a
minimal exact sparse-polynomial algebra to check the universal differential
identity on a generic two-variable polynomial.  Later coefficient-map gates
are appended here only after both producers have frozen their outputs.
"""

from __future__ import annotations

from fractions import Fraction
from hashlib import sha256
from itertools import product
